import React, { Component } from 'react';
import classes from './Marketplace.css';
import Genomics from '../../containers/GenomicsForm/GenomicsForm';
import Dicom from '../../containers/DicomForm/DicomForm';

class Marketplace extends Component {
    state = {
        genomicsForm : false,
        dicomForm : false
    }

    genomicsFormHandler = () => {
        this.setState( { genomicsForm : true, 
                         dicomForm : false })
    }

    dicomFormHandler = () => {
        this.setState( { dicomForm : true,
                         genomicsForm: false })
    }

    render() {

        let genomicsForm = null;
        let dicomForm = null;

        if (this.state.genomicsForm) {
            genomicsForm = <Genomics contract={this.props.contract}
                                     accounts={this.props.accounts}
                                     web3={this.props.web3}
                                     />
        }

        if (this.state.dicomForm) {
            dicomForm = <Dicom contract={this.props.contract}
                               accounts={this.props.accounts}
                               web3={this.props.web3}
                               />
        }

        return (
            <div className={classes.Marketplace}>
               <h2> ¡Welcome to the Marketplace! </h2>
               <h4> Please select which type of data are you looking for: </h4>
                <div className={classes.Options}>
                    <button className={classes.Edit} onClick={this.genomicsFormHandler}> GENOMICS </button>
                    <button className={classes.Edit} onClick={this.dicomFormHandler}> DICOM </button>
                </div>
                <section> 
                    {genomicsForm}
                </section>
                <section> 
                    {dicomForm}
                </section>
            </div>
        )}
    }

export default Marketplace;
